"use strict";

(function () {
  const SVG_NS = "http://www.w3.org/2000/svg";
  const BASE_WIDTH = 1018;
  const BASE_HEIGHT = 708;

  const DEFAULT_TITLE = "LÍNEA 3 / PRENSA";
  const DEFAULT_SUBTITLE = "Esquema de prensa y sensores";

  const SENSORS = [
    { tag: "-B644", type: "left", x: 116, y: 26,  tx: 132, ty: 25,  align: "middle" },
    { tag: "-B643", type: "left", x: 116, y: 68,  tx: 132, ty: 67,  align: "middle" },
    { tag: "-B642", type: "left", x: 116, y: 110, tx: 132, ty: 109, align: "middle" },
    { tag: "-B641", type: "left", x: 116, y: 152, tx: 132, ty: 151, align: "middle" },

    // Ocho unidades libres hasta el borde gris situado en x = 50.
    { tag: "-B624", type: "left", x: 61, y: 192, tx: 42, ty: 210, align: "end", vertical: true },
    { tag: "-B623", type: "left", x: 61, y: 226, tx: 42, ty: 244, align: "end", vertical: true },
    { tag: "-B622", type: "left", x: 61, y: 260, tx: 42, ty: 278, align: "end", vertical: true },
    { tag: "-B621", type: "left", x: 61, y: 294, tx: 42, ty: 312, align: "end", vertical: true },

    { tag: "-B661", type: "left", x: 116, y: 344, tx: 132, ty: 342, align: "middle" },
    { tag: "-B662", type: "left", x: 166, y: 344, tx: 182, ty: 342, align: "middle" },

    { tag: "-B604", type: "left", x: 165, y: 412, tx: 181, ty: 411, align: "middle" },
    { tag: "-B603", type: "left", x: 165, y: 454, tx: 181, ty: 453, align: "middle" },
    { tag: "-B602", type: "left", x: 165, y: 496, tx: 181, ty: 495, align: "middle" },
    { tag: "-B601", type: "left", x: 165, y: 538, tx: 181, ty: 537, align: "middle" },

    { tag: "-B681", type: "right", x: 319, y: 59,  tx: 356, ty: 76,  align: "start", vertical: true },
    { tag: "-B682", type: "right", x: 319, y: 100, tx: 356, ty: 117, align: "start", vertical: true },
    { tag: "-B683", type: "right", x: 319, y: 141, tx: 356, ty: 158, align: "start", vertical: true },
    { tag: "-B684", type: "right", x: 319, y: 182, tx: 356, ty: 199, align: "start", vertical: true },

    { tag: "-B621", type: "right", x: 743, y: 110, tx: 760, ty: 106, align: "middle", hatchGap: true },

    { tag: "-B701", type: "right", x: 487, y: 256, tx: 504, ty: 252, align: "middle", hatchGap: true },
    { tag: "-B702", type: "right", x: 537, y: 256, tx: 554, ty: 252, align: "middle", hatchGap: true },
    { tag: "-B703", type: "right", x: 587, y: 256, tx: 604, ty: 252, align: "middle", hatchGap: true },
    { tag: "-B704", type: "right", x: 715, y: 249, tx: 732, ty: 245, align: "middle", hatchGap: true },
    { tag: "-B705", type: "right", x: 783, y: 256, tx: 800, ty: 252, align: "middle", hatchGap: true },
    { tag: "-B706", type: "right", x: 833, y: 256, tx: 850, ty: 252, align: "middle", hatchGap: true },
    { tag: "-B707", type: "right", x: 883, y: 256, tx: 900, ty: 252, align: "middle", hatchGap: true }
  ];

  let root;
  let stage;
  let latestWidget = null;
  let currentName = null;
  let initialized = false;

  function svgElement(tag, attributes, parent, content) {
    const node = document.createElementNS(SVG_NS, tag);

    Object.keys(attributes).forEach(function (key) {
      node.setAttribute(key, String(attributes[key]));
    });

    if (content !== undefined) {
      node.textContent = content;
    }

    parent.appendChild(node);
    return node;
  }

  function drawSensors() {
    const layer = document.getElementById("press-sensors");
    const hatchGaps = document.getElementById("press-hatch-gaps");

    if (!layer || !hatchGaps) return;

    layer.replaceChildren();
    hatchGaps.replaceChildren();

    SENSORS.forEach(function (sensor) {
      const group = svgElement("g", {}, layer);
      const isLeft = sensor.type === "left";

      svgElement(
        "use",
        {
          href: isLeft
            ? "#press-sensor-left"
            : "#press-sensor-right",
          x: sensor.x,
          y: sensor.y,
          width: isLeft ? 29 : 37,
          height: isLeft ? 29 : 35
        },
        group
      );

      // Marco real del símbolo, sin los márgenes del viewBox.
      const frameX = sensor.x + (isLeft ? 3 : 2);
      const frameY = sensor.y + (isLeft ? 3 : 1);
      const frameSize = isLeft ? 25 : 31;

      const textAttributes = {
        class: "sensor-tag",
        x: sensor.align === "middle"
          ? frameX + frameSize / 2
          : sensor.tx,
        y: sensor.vertical
          ? frameY + frameSize / 2
          : sensor.ty,
        "text-anchor": sensor.align
      };

      // Esta propiedad centra las etiquetas laterales; no gira el símbolo.
      if (sensor.vertical) {
        textAttributes["dominant-baseline"] = "central";
      }

      const text = svgElement(
        "text",
        textAttributes,
        group,
        sensor.tag
      );

      if (!sensor.vertical) {
        const bounds = text.getBBox();
        const excess = bounds.y + bounds.height - (frameY - 4);

        // Corrección pequeña para separar el texto del borde superior.
        if (excess > 0) {
          text.setAttribute(
            "y",
            sensor.ty - Math.min(excess, 4)
          );
        }
      }

      if (sensor.hatchGap) {
        const bounds = text.getBBox();

        // Retira únicamente el rayado que queda detrás de la etiqueta.
        svgElement(
          "rect",
          {
            x: bounds.x - 4,
            y: bounds.y - 3,
            width: bounds.width + 8,
            height: bounds.height + 6,
            fill: "black"
          },
          hatchGaps
        );
      }
    });
  }

  function updateHeader(widget) {
    if (!stage) return;

    const name =
      widget && typeof widget.name === "string"
        ? widget.name.trim()
        : "";

    if (name === currentName) return;
    currentName = name;

    const parts = name.split("//");
    const title =
      (parts[0] || "").trim() || DEFAULT_TITLE;

    const subtitle =
      parts.length > 1
        ? parts.slice(1).join("//").trim()
        : DEFAULT_SUBTITLE;

    const titleNode = stage.querySelector(".screen-title");
    const subtitleNode = stage.querySelector(".screen-subtitle");

    titleNode.textContent = title;
    subtitleNode.textContent = subtitle;
    subtitleNode.hidden = subtitle === "";
  }

  function fitStage() {
    if (!root || !stage) return;

    const width = root.clientWidth;
    const height = root.clientHeight;

    if (width <= 0 || height <= 0) return;

    const scale = Math.min(
      width / BASE_WIDTH,
      height / BASE_HEIGHT
    );

    stage.style.left =
      (width - BASE_WIDTH * scale) / 2 + "px";

    stage.style.top =
      (height - BASE_HEIGHT * scale) / 2 + "px";

    stage.style.transform = "scale(" + scale + ")";
  }

  // Widget sin tags del PLC.
  window.onWidgetUpdate = function (widget) {
    latestWidget = widget;

    if (initialized) {
      updateHeader(widget);
    }
  };

  function initialize() {
    if (initialized) return;

    root = document.querySelector(".press-widget");
    stage = document.querySelector(".press-stage");

    if (!root || !stage) return;

    drawSensors();

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(drawSensors);
    }

    initialized = true;

    updateHeader(latestWidget || window.WIDGET || null);
    fitStage();

    if (typeof ResizeObserver !== "undefined") {
      new ResizeObserver(fitStage).observe(root);
    } else {
      window.addEventListener("resize", fitStage);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initialize, {
      once: true
    });
  } else {
    initialize();
  }
})();
